// Presupuesto de atención de una persona. Todos los supuestos son inventados
// y están arriba para que los cambies: lo que importa es la forma de la cuenta.
const HORAS_MES = 160;        // trabajo de una persona en un mes
const HORAS_POR_PIEZA = 6;    // por pieza que hay que operar: actualizar, mirar alarmas, rotar claves
const DISP_PIEZA = 0.999;     // cada pieza anda el 99,9 % del tiempo
const MIN_MES = 30 * 24 * 60; // minutos de un mes de 30 días

function cuenta(nombre, piezas, piezasPorPedido) {
  const operar = piezas * HORAS_POR_PIEZA;
  const libres = HORAS_MES - operar;
  const caminos = piezas * (piezas - 1) / 2;   // como máximo, cada pieza puede hablar con cada otra
  const disp = Math.pow(DISP_PIEZA, piezasPorPedido);
  const caidaMin = (1 - disp) * MIN_MES;
  console.log(
    nombre.padEnd(24) +
    String(piezas).padStart(3) + " piezas | " +
    String(caminos).padStart(3) + " caminos posibles | " +
    String(operar).padStart(3) + " h de operación | " +
    String(libres).padStart(4) + " h para producto | " +
    caidaMin.toFixed(0).padStart(3) + " min caídos/mes");
}

//        nombre                    piezas    piezas que cruza un pedido
cuenta("app + base gestionada",       3,        2);
cuenta("monolito + base + cola",      5,        3);
cuenta("6 servicios",           6 * 3 + 3,      5);  // por servicio: programa, base y pipeline; más balanceador, cola y monitoreo
cuenta("12 servicios",         12 * 3 + 3,      7);
console.log("Horas negativas: la operación pedida no entra en una persona.");
